import tarfile
import os
def extract_and_rotate_images(tar_path):
    tar = tarfile.open(tar_path)
    tar.extractall('/tmp/')
    tar.close()

    for root, dirs, files in os.walk('/tmp'):
        for file in files:
            if file.endswith('.jpg'):
                jpg_path = os.path.join(root, file)
                rot_path = jpg_path + '.rot'
                os.rename(jpg_path, rot_path)

extract_and_rotate_images('images.tar.gz')
